<!--
/**
 * @component Populate
 *
 * This component is used to fetch and display the value of a nested property from a given source object or from local/session storage.
 *
 * @prop {string} prop - A string representing the path to the nested property. The path should be dot-separated. For example, 'user.profile.name'.
 * @prop {string} fallback - A fallback value to display if the nested property is not found or its value is falsy.
 * @prop {Object} source - An object from which to fetch the nested property. If not provided, the component will try to fetch the property from local/session storage.
 *
 * @example
 * <Populate prop="user.profile.name" fallback="friend" source={user} />
 *
 * In this example, the component will display the user's name if it exists. If the user's name is not found or its value is falsy, it will display 'N/A'.
 */
-->

<script>
  import { isEmpty } from '@splendidlabz/utils'
  import { onMount } from 'svelte'
  import { getValueFromBrowserStorage, getValueFromSource } from './get-value'

  export let prop = ''
  export let fallback = ''
  export let source = {}

  let value
  const list = prop.split('.')

  // If source is provided, draw from source
  if (!isEmpty(source)) value = getValueFromSource({ source, list })

  // If source is not provided, draw from localStorage, sessionstorage or query parameters (in this order) — in this case client:load is required.
  if (isEmpty(source)) {
    onMount(async _ => {
      value = getValueFromBrowserStorage(list)
    })
  }
</script>

{#if value}
  {value}
{:else}
  {fallback}
{/if}
